from pathlib import Path
import json,shlex,subprocess
root=Path('/Users/Shared/Projects/RunnerHub/Business');p=Path(__file__).resolve().parent
helpers=(root/'_codex/scripts/deploy_estudo.py').read_text().split('def remote(')[0].replace('ROOT=Path(__file__).resolve().parents[2]',"ROOT=Path('/var/www/business.roadrunners.run')")
sql="SELECT jsonb_build_object('current_user',current_user,'version',version(),'history_exists',to_regclass('public.tb_evento_fatos_historico') IS NOT NULL,'function_exists',to_regprocedure('public.registra_evento_fatos_historico()') IS NOT NULL,'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rows_estimate',c.reltuples)) FROM pg_class c WHERE c.oid IN ('public.tb_evento_corridas'::regclass,'public.tb_evento_corridas_percursos'::regclass)),'columns',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type) ORDER BY table_name,ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('tb_evento_corridas','tb_evento_corridas_percursos')),'triggers',(SELECT jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid),'function',tgfoid::regprocedure::text,'body',pg_get_functiondef(tgfoid)) ORDER BY tgrelid,tgname) FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN ('public.tb_evento_corridas'::regclass,'public.tb_evento_corridas_percursos'::regclass)),'defaults',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(defaclrole),'namespace',defaclnamespace,'type',defaclobjtype,'acl',defaclacl)) FROM pg_default_acl))::text payload"
remote=helpers+'\np=json.load(sys.stdin)\nr=bridge(ROOT,raw_query(p["sql"])+"report=deserializeJSON(q.payload[1]);")\nprint(json.dumps(r))'
cp=subprocess.run(['ssh','-o','BatchMode=yes','-o','ConnectTimeout=10','-o','StrictHostKeyChecking=yes','-i','/Users/leonardosobral/.ssh/webs','root@ssh.runnerhub.run','python3 -c '+shlex.quote(remote)],input=json.dumps({'sql':sql}),capture_output=True,text=True,timeout=100)
if cp.returncode:raise RuntimeError(cp.stderr[-2000:])
r=json.loads(cp.stdout);(p/'production-inspection.json').write_text(json.dumps(r,indent=2,ensure_ascii=False));print(json.dumps({k:r[k] for k in ['current_user','version','history_exists','function_exists','tables']},ensure_ascii=False))
